using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class RebirthCamperCollisionSurvey
{
 public const string Output="E:/_Haven/shared/REBIRTHStaged/VehicleStudio/CamperPhysicalCollision_20261018";
 public static void Run(){Directory.CreateDirectory(Output);var root=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(RebirthCamperDoorHardwareFix.Folder+"/rebirthCamper80s.prefab"));var lines=new List<string>();foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){if(new[]{"camper_interior","camper_body","parts","body"}.Contains(f.name)||f.name.StartsWith("RearDoor_")){var b=f.GetComponent<Renderer>().bounds;lines.Add("MESH "+f.name+" bounds="+b.center.ToString("F4")+" size="+b.size.ToString("F4")+" layer="+f.gameObject.layer);if(f.name=="camper_interior")foreach(var c in RebirthCamperDoorHardwareAudit.Components(f))lines.Add("INTERIOR tris="+c.Indices.Count/3+" sub="+c.Sub+" bounds="+c.Bounds.center.ToString("F4")+" size="+c.Bounds.size.ToString("F4"));}}foreach(var c in root.GetComponentsInChildren<Collider>(true))lines.Add("COLLIDER "+c.name+" type="+c.GetType().Name+" layer="+c.gameObject.layer+" active="+c.gameObject.activeInHierarchy+" enabled="+c.enabled+" trigger="+c.isTrigger);File.WriteAllLines(Output+"/survey.txt",lines);Object.DestroyImmediate(root);}
}
